using UnityEngine;
using UnityEngine.UI;

public class PuzzleTimer : MonoBehaviour
{
    [SerializeField] private Text timerLabel;
    [SerializeField] private Text hintLabel;
    [SerializeField] private AudioSource alarmSound;
    [SerializeField] private GameObject solutionPanel;

    private float timeRemaining = 30f;
    private bool hintShown = false;
    private bool alarmPlayed = false;
    private bool solutionShown = false;
    private bool timerActive = true;

    private void Update()
    {
        if (!timerActive) return;

        timeRemaining -= Time.deltaTime;
        timerLabel.text = Mathf.CeilToInt(timeRemaining).ToString();

        if (timeRemaining <= 20f && !hintShown)
        {
            hintLabel.gameObject.SetActive(true);
            hintShown = true;
        }

        if (timeRemaining <= 10f && !alarmPlayed)
        {
            alarmSound.Play();
            alarmPlayed = true;
        }

        if (timeRemaining <= 0f && !solutionShown)
        {
            solutionPanel.SetActive(true);
            solutionShown = true;
            timerActive = false;
        }
    }

    public void ResetTimer()
    {
        timeRemaining = 30f;
        hintShown = false;
        alarmPlayed = false;
        solutionShown = false;
        timerActive = true;
    }
}

