// PuzzleTimer.cs — Corrutina con WaitForSeconds
using System.Collections;
using UnityEngine;
using UnityEngine.UI;

public class PuzzleTimer : MonoBehaviour
{
    [SerializeField] private Text timerLabel;
    [SerializeField] private Text hintLabel;
    [SerializeField] private AudioSource alarmSound;
    [SerializeField] private GameObject solutionPanel;

    private Coroutine _timerCoroutine;

    private void Start()
    {
        StartCountdown();
    }

    public void StartCountdown()
    {
        if (_timerCoroutine != null)
            StopCoroutine(_timerCoroutine);

        hintLabel.gameObject.SetActive(false);
        solutionPanel.SetActive(false);
        _timerCoroutine = StartCoroutine(CountdownRoutine(30));
    }

    private IEnumerator CountdownRoutine(int totalSeconds)
    {
        int remaining = totalSeconds;

        while (remaining > 0)
        {
            timerLabel.text = remaining.ToString();

            // Espera exactamente 1 segundo sin ocupar Update
            yield return new WaitForSeconds(1f);
            remaining--;

            if (remaining == 20)
                hintLabel.gameObject.SetActive(true);

            if (remaining == 10)
                alarmSound.Play();
        }

        timerLabel.text = "0";
        solutionPanel.SetActive(true);
    }

    private void OnDisable()
    {
        if (_timerCoroutine != null)
            StopCoroutine(_timerCoroutine);
    }
}

