// LevelUpAnimator.cs — Corrutina secuencial
using System.Collections;
using UnityEngine;
using UnityEngine.UI;

public class LevelUpAnimator : MonoBehaviour
{
    [SerializeField] private SpriteRenderer characterSprite;
    [SerializeField] private ParticleSystem levelParticles;
    [SerializeField] private GameObject statsPopup;

    public void TriggerLevelUp()
    {
        StartCoroutine(LevelUpSequence());
    }

    private IEnumerator LevelUpSequence()
    {
        // Paso 1: Resplandor dorado
        characterSprite.color = Color.yellow;
        yield return new WaitForSeconds(0.8f);

        // Paso 2: Escalar personaje
        characterSprite.color = Color.white;
        yield return ScaleTo(characterSprite.transform, Vector3.one * 1.2f, 0.3f);
        yield return ScaleTo(characterSprite.transform, Vector3.one, 0.2f);

        // Paso 3: Partículas
        levelParticles.Play();
        yield return new WaitForSeconds(1f);

        // Paso 4: Mostrar UI
        statsPopup.SetActive(true);
    }

    private IEnumerator ScaleTo(Transform target, Vector3 endScale, float duration)
    {
        Vector3 startScale = target.localScale;
        float elapsed = 0f;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            target.localScale = Vector3.Lerp(startScale, endScale, elapsed / duration);
            yield return null;
        }

        target.localScale = endScale;
    }

    private void OnDisable()
    {
        StopAllCoroutines();
        characterSprite.color = Color.white;
        characterSprite.transform.localScale = Vector3.one;
    }
}

