// SceneLoader.cs — Carga asíncrona con barra de progreso real
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class SceneLoader : MonoBehaviour
{
    [SerializeField] private Slider progressBar;
    [SerializeField] private Text loadingLabel;
    [SerializeField] private string nextScene = "Level_02";

    private void Start()
    {
        StartCoroutine(LoadSceneAsync(nextScene));
    }

    private IEnumerator LoadSceneAsync(string sceneName)
    {
        loadingLabel.text = "Cargando...";
        progressBar.value = 0f;

        // Inicia la carga en segundo plano sin activar la escena todavía
        AsyncOperation operation = SceneManager.LoadSceneAsync(sceneName);
        operation.allowSceneActivation = false;

        while (!operation.isDone)
        {
            // progress va de 0.0 a 0.9 mientras carga; 0.9 significa listo
            float realProgress = Mathf.Clamp01(operation.progress / 0.9f);
            progressBar.value = realProgress;
            loadingLabel.text = $"Cargando... {Mathf.RoundToInt(realProgress * 100f)}%";

            // Cuando llega al 90 %, la escena está lista en memoria
            if (operation.progress >= 0.9f)
            {
                progressBar.value = 1f;
                loadingLabel.text = "¡Listo! Presiona cualquier tecla";

                // Espera input del jugador antes de activar
                yield return new WaitUntil(() => Input.anyKeyDown);
                operation.allowSceneActivation = true;
            }

            yield return null;
        }
    }
}

