using System.Collections;
using UnityEngine;

public class UIFader : MonoBehaviour
{
    [SerializeField] private CanvasGroup canvasGroup;
    [SerializeField] private float fadeDuration = 0.5f;

    private Coroutine _currentFade;

    public void FadeIn()
    {
        gameObject.SetActive(true);
        if (_currentFade != null) StopCoroutine(_currentFade);
        _currentFade = StartCoroutine(Fade(canvasGroup.alpha, 1f, fadeDuration));
    }

    public void FadeOut()
    {
        if (_currentFade != null) StopCoroutine(_currentFade);
        _currentFade = StartCoroutine(FadeAndHide());
    }

    private IEnumerator FadeAndHide()
    {
        yield return Fade(canvasGroup.alpha, 0f, fadeDuration);
        gameObject.SetActive(false);
    }

    // Corrutina genérica: anima alpha de 'from' a 'to' en 'duration' segundos
    private IEnumerator Fade(float from, float to, float duration)
    {
        float elapsed = 0f;
        canvasGroup.alpha = from;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            canvasGroup.alpha = Mathf.Lerp(from, to, elapsed / duration);
            yield return null;
        }

        canvasGroup.alpha = to;
    }

    private void OnDisable()
    {
        if (_currentFade != null)
            StopCoroutine(_currentFade);
    }
}

