using UnityEngine;
using UnityEngine.UI;

public class DialogueTypewriter : MonoBehaviour
{
    [SerializeField] private Text dialogueText;
    [SerializeField] private float charDelay = 0.05f;

    private string fullText = "";
    private int charIndex = 0;

    public void ShowDialogue(string text)
    {
        fullText = text;
        charIndex = 0;
        dialogueText.text = "";

        // InvokeRepeating no puede recibir el texto como parámetro
        // Si se llama de nuevo antes de terminar, el charIndex se desincroniza
        CancelInvoke("ShowNextChar");
        InvokeRepeating("ShowNextChar", 0f, charDelay);
    }

    private void ShowNextChar()
    {
        if (charIndex < fullText.Length)
        {
            dialogueText.text += fullText[charIndex];
            charIndex++;
        }
        else
        {
            CancelInvoke("ShowNextChar");
        }
    }

    // Bug: si el jugador presiona Skip, el charIndex queda
    // en un valor arbitrario para el siguiente diálogo
    public void Skip()
    {
        CancelInvoke("ShowNextChar");
        dialogueText.text = fullText;
    }
}

