using System.Collections;
using UnityEngine;
using UnityEngine.UI;

public class DialogueTypewriter : MonoBehaviour
{
    [SerializeField] private Text dialogueText;
    [SerializeField] private float defaultCharDelay = 0.05f;

    private Coroutine _typingCoroutine;
    private string _currentFullText = "";

    public void ShowDialogue(string text, float charDelay = -1f)
    {
        _currentFullText = text;
        float delay = charDelay < 0f ? defaultCharDelay : charDelay;

        if (_typingCoroutine != null)
            StopCoroutine(_typingCoroutine);

        _typingCoroutine = StartCoroutine(TypeText(text, delay));
    }

    private IEnumerator TypeText(string text, float charDelay)
    {
        dialogueText.text = "";

        foreach (char c in text)
        {
            dialogueText.text += c;
            yield return new WaitForSeconds(charDelay);
        }

        _typingCoroutine = null;
    }

    public void Skip()
    {
        if (_typingCoroutine != null)
        {
            StopCoroutine(_typingCoroutine);
            _typingCoroutine = null;
        }
        dialogueText.text = _currentFullText;
    }

    private void OnDisable()
    {
        if (_typingCoroutine != null)
            StopCoroutine(_typingCoroutine);
    }
}

