using UnityEngine;

public class WaveSpawner : MonoBehaviour
{
    public enum WaveState { Idle, VFormation, Line, Circle }

    [SerializeField] private GameObject enemyPrefab;
    [SerializeField] private Transform spawnOrigin;

    private WaveState currentState = WaveState.Idle;
    private float spawnTimer = 0f;
    private int spawnedCount = 0;
    private int totalToSpawn = 0;

    private void Update()
    {
        spawnTimer -= Time.deltaTime;
        if (spawnTimer > 0f) return;

        switch (currentState)
        {
            case WaveState.VFormation:
                if (spawnedCount < totalToSpawn)
                {
                    Vector3 pos = GetVPosition(spawnedCount);
                    Instantiate(enemyPrefab, pos, Quaternion.identity);
                    spawnedCount++;
                    spawnTimer = 0.3f;
                }
                else { currentState = WaveState.Idle; }
                break;

            case WaveState.Line:
                if (spawnedCount < totalToSpawn)
                {
                    Vector3 pos = GetLinePosition(spawnedCount);
                    Instantiate(enemyPrefab, pos, Quaternion.identity);
                    spawnedCount++;
                    spawnTimer = 0.2f;
                }
                else { currentState = WaveState.Idle; }
                break;

            case WaveState.Circle:
                if (spawnedCount < totalToSpawn)
                {
                    Vector3 pos = GetCirclePosition(spawnedCount, totalToSpawn);
                    Instantiate(enemyPrefab, pos, Quaternion.identity);
                    spawnedCount++;
                    spawnTimer = 0.15f;
                }
                else { currentState = WaveState.Idle; }
                break;
        }
    }

    private Vector3 GetVPosition(int index) =>
        spawnOrigin.position + new Vector3(index % 2 == 0 ? index : -index, 0f, index * 0.5f);

    private Vector3 GetLinePosition(int index) =>
        spawnOrigin.position + new Vector3(index * 1.5f - totalToSpawn * 0.75f, 0f, 0f);

    private Vector3 GetCirclePosition(int index, int total)
    {
        float angle = index * Mathf.PI * 2f / total;
        return spawnOrigin.position + new Vector3(Mathf.Cos(angle) * 5f, 0f, Mathf.Sin(angle) * 5f);
    }

    public void StartVFormation(int count) { totalToSpawn = count; spawnedCount = 0; currentState = WaveState.VFormation; }
    public void StartLine(int count) { totalToSpawn = count; spawnedCount = 0; currentState = WaveState.Line; }
    public void StartCircle(int count) { totalToSpawn = count; spawnedCount = 0; currentState = WaveState.Circle; }
}

