        Debug.Log($"Zona cargada: {loadedAssets.Count} assets instanciados");
    }

    private void OnTriggerExit(Collider other)
    {
        if (!other.CompareTag("Player")) return;

        // No libera memoria: los assets quedan en RAM indefinidamente
        foreach (var asset in loadedAssets)
            Destroy(asset);

        loadedAssets.Clear();
        // Resources.UnloadUnusedAssets() tampoco se llama
    }
}

