using System.Collections.Generic;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

public class ZoneLoader : MonoBehaviour
{
    [SerializeField] private List<AssetReference> zoneAssets;

    private readonly List<AsyncOperationHandle<GameObject>> _handles =
        new List<AsyncOperationHandle<GameObject>>();
    private readonly List<GameObject> _instances =
        new List<GameObject>();

    private void OnTriggerEnter(Collider other)
    {
        if (!other.CompareTag("Player")) return;
        LoadZoneAsync();
    }

    private async void LoadZoneAsync()
    {
        foreach (var assetRef in zoneAssets)
        {
            // Carga en segundo plano — no bloquea el hilo principal
            AsyncOperationHandle<GameObject> handle =
                Addressables.LoadAssetAsync<GameObject>(assetRef);

            await handle.Task;

            if (handle.Status == AsyncOperationStatus.Succeeded)
            {
                GameObject instance = Instantiate(
                    handle.Result, transform.position, Quaternion.identity);
                _instances.Add(instance);
                _handles.Add(handle);
            }
            else
            {
                Debug.LogError($"Error cargando asset: {assetRef}");
                Addressables.Release(handle);
            }
        }

        Debug.Log($"Zona lista: {_instances.Count} assets cargados");
    }

    private void OnTriggerExit(Collider other)
    {
        if (!other.CompareTag("Player")) return;
        UnloadZone();
    }

    private void UnloadZone()
    {
        foreach (var instance in _instances)
            Destroy(instance);
        _instances.Clear();

        // Libera la memoria de los assets descargados
        foreach (var handle in _handles)
            Addressables.Release(handle);
        _handles.Clear();
    }

    private void OnDestroy()
    {
        UnloadZone();
    }
}

