using System.Collections;
using UnityEngine;

public class EnemyPatrol : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float moveSpeed = 3f;
    [SerializeField] private float waitTime = 1f;

    private int currentWaypoint = 0;

    private void Start()
    {
        // La corrutina inicia pero nunca se cancela explícitamente
        StartCoroutine(Patrol());
    }

    private IEnumerator Patrol()
    {
        while (true)
        {
            Transform target = waypoints[currentWaypoint];

            // Si el objeto es destruido aquí, transform lanza NullReferenceException
            while (Vector3.Distance(transform.position, target.position) > 0.1f)
            {
                transform.position = Vector3.MoveTowards(
                    transform.position,
                    target.position,
                    moveSpeed * Time.deltaTime
                );
                yield return null;
            }

            currentWaypoint = (currentWaypoint + 1) % waypoints.Length;
            // Pausa entre waypoints — si el objeto se destruye aquí,
            // Unity intentará continuar en el siguiente frame
            yield return new WaitForSeconds(waitTime);
        }
    }

    // No hay OnDisable ni OnDestroy — la corrutina no se cancela nunca
}

