using System.Collections;
using System.Threading;
using UnityEngine;

public class EnemyPatrol : MonoBehaviour
{
    [SerializeField] private Transform[] waypoints;
    [SerializeField] private float moveSpeed = 3f;
    [SerializeField] private float waitTime = 1f;

    private int _currentWaypoint = 0;
    private Coroutine _patrolCoroutine;
    private CancellationTokenSource _cts;

    private void OnEnable()
    {
        _cts = new CancellationTokenSource();
        _patrolCoroutine = StartCoroutine(Patrol());
    }

    private void OnDisable()
    {
        // Cancela el token para detener loops async si los hay
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;

        // Detiene la corrutina de Unity antes de que el objeto se desactive
        if (_patrolCoroutine != null)
        {
            StopCoroutine(_patrolCoroutine);
            _patrolCoroutine = null;
        }
    }

    private void OnDestroy()
    {
        // OnDisable siempre se llama antes de OnDestroy en Unity,
        // pero lo duplicamos por claridad y robustez
        StopAllCoroutines();
    }

    private IEnumerator Patrol()
    {
        while (this != null && enabled)
        {
            if (waypoints == null || waypoints.Length == 0)
                yield break;

            Transform target = waypoints[_currentWaypoint];

            while (target != null &&
                   Vector3.Distance(transform.position, target.position) > 0.1f)
            {
                transform.position = Vector3.MoveTowards(
                    transform.position,
                    target.position,
                    moveSpeed * Time.deltaTime
                );
                yield return null;
            }

            _currentWaypoint = (_currentWaypoint + 1) % waypoints.Length;
            yield return new WaitForSeconds(waitTime);
        }
    }
}
